/* English localization + encoding repair layer (peeled from app.js).
 * Load after assets/js/app/app.js (or any time after DOM globals exist).
 * Auto-installs on parse.
 */
// ENGLISH LOCALIZATION LAYER (auto-applies to static + dynamic UI)
function decodeReplacementKey(base64) {
    try {
        if (typeof atob === 'function' && typeof TextDecoder !== 'undefined') {
            const binary = atob(base64);
            const bytes = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
            return new TextDecoder('utf-8', { fatal: false }).decode(bytes);
        }
    } catch (error) {}
    try {
        if (typeof Buffer !== 'undefined') return Buffer.from(base64, 'base64').toString('utf8');
    } catch (error) {}
    return '';
}

